	aliases = { "равнины Мулгора" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мулгор — родина {link:tauren}тауренов{/link}, широкий край золотой травы и пологих холмов, со всех сторон {link:ogres}огр{/link}ажденный горами. На его равнинах пасутся стада кодо, а чистые колодцы и озера поят землю. Над всем этим высятся огромные столовые горы {link:thunder-bluff}Громового Утеса{/link}, столицы тауренов, где держит свой шатер верховный вождь {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link}. Для тауренов это дар {red:earth-mother}Матери-Земли{/red}, мирная земля после веков скитаний. И все же {link:quilboar}свинобраз{/link}ы, {link:gnolls}гнолл{/link}ы, гарпии и гоблины теснят ее с каждого края, и молодые воины племен должны показать себя в борьбе с ними.]=],
