	sections = {
		{
			title = "Обзор",
			text = [=[Плато Красного Облака — высокое нагорье на юге {link:mulgore}Мулгор{/link}а, где молодые {link:tauren}таурен{/link}ы делают первые шаги на пути охотника. В его травах бродят равнинные долгоноги и горные пумы, и старейшины говорят, что его жители больше всего гордятся искусной охотой. К юго-востоку от лагеря лежит колодец, где набирает воду Праматерь рода Ястребиного Ветра. В холмах на юге обитает провидец {link:seer-graytongue}Серый Язык{/link}, а над дальними юго-восточными склонами стоит святилище Ан'ше и Му'ша. К востоку от плато открывается {link:brambleblade-ravine}Ежевичная лощина{/link}, откуда {link:bristleback-quilboar}свинобразы Дыбогривы{/link} приходят по ночам, чтобы подстерегать охотников и красть из лагеря.]=],
		},
	},
})

Translate("ruRU", "camp-narache", {
