		},
	},
})

Translate("ruRU", "water-wells-of-mulgore", {
	title = "Колодцы Мулгора",
	aliases = { "Колодец Заиндевевшего Копыта", "Колодец Громового Рога", "Колодец Буйногривых", "колодцы Мулгора" },
	sections = {
		{
			title = "Обзор",
			text = [=[Три священных колодца поят {link:mulgore}равнины Мулгора{/link}, и каждый назван в честь одного из кланов {link:tauren}таурен{/link}ов. Колодец Заиндевевшего Копыта лежит к юго-востоку от Деревни Кровавого Копыта, Колодец Громового Рога — к северу от нее, а Колодец Буйногривых — к северу от Громового Утеса. Колодцы дают жизнь тауренам и зверям, от которых те зависят. Гоблины {link:venture-company}Торговой Компании{/link} и их слуги осквернили все три. Чтобы очистить их, шаман {link:mull-thunderhorn}Мулл Громовой Рог{/link} делает для каждого тотем из того, что дает сама земля, а затем у колодца нужно совершить обряд — нередко на глазах у гоблинской стражи.]=],
		},
	},
})

Translate("ruRU", "the-venture-co-mine", {
