	sections = {
		{
			title = "Обзор",
			text = [=[Золотые равнины простираются к востоку от Громового Утеса — море высокой травы между городом и восточными утесами. Здесь охотятся равнинные пумы, и, как говорят, в тех же краях бродит старый долгоног {link:mazzranache}Маззранач{/link}. Время от времени эти равнины пересекает {link:ogres}огр{/link}омный белый волк по кличке {link:ghost-howl}Призрачный Вой{/link}, чья шкура до сих пор несет шрамы от битвы с демонами. Гоблины Торговой Компании прокладывают через травы свои дороги между рудником и колодцами. В эти дни на равнинах видели один из их крошителей — машину, которой {link:tauren}таурен{/link}ы не позволят свалить ни единого дерева {link:mulgore}Мулгор{/link}а.]=],
		},
	},
})

Translate("ruRU", "camp-gev-rek", {
