Translate("ruRU", "baine-bloodhoof", {
	title = "Бейн Кровавое Копыто",
	subtitle = "Вождь Деревни Кровавого Копыта",
	found = "Центр Деревни Кровавого Копыта",
	hint = [=[Найдите сына верховного вождя, который возглавляет Деревню Кровавого Копыта.]=],
