		},
		{
			title = "Значение",
			text = [=[Бейн — следующее поколение рода Кровавого Копыта. Молодые, что проходят через его деревню, узнают от него, что значит защищать родину {link:tauren}таурен{/link}ов.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он продолжает {link:rites-of-the-earthmother}Обряды Матери-Земли{/link} и посылает молодых к духовному наставнику {link:zarlman-two-moons}Зарлман{/link}у Двум Лунам для обряда Видения.
• Он приказал отбросить {link:gnolls}гнолл{/link}ов Бледн{link:ogres}огр{/link}ивов, когда те отвергли все попытки мира.
• Он приказал уничтожить инструменты {link:dwarves}дворф{/link}ов-землекопов.
• Порой он обращается за помощью к дальним ходокам, разведчикам своего отца.
• В эти дни он возглавил оборону против набега {link:centaurs}кентавр{/link}ов Галак.]=],
		},
	},
	chapters = {
		{
			title = "Делить землю",
			hint = "Узнайте суждение вождя о гноллах Мулгора.",
			text = [=[{link:palemane-gnolls}Гноллы Бледногривы{/link} пришли в {link:mulgore}Мулгор{/link} и без удержу истребляли его зверей. {link:tauren}Таурены{/link} снова и снова пытались достучаться до них словами. {link:nak}Нак{/link}онец Бейн заключил, что слова больше не ответ. Он хотел показать молодым, какой страшной может стать даже малая угроза, если оставить ее без присмотра.]=],
		},
		{
			title = "Наш древний враг",
			hint = "Разберитесь с кентаврами, которые перешли границу Мулгора.",
			text = [=[Когда до него дошло донесение убитой, дальнего ходока Малы, Бейн прочел его молча. Затем он объявил, что {link:tauren}таурен{/link}ы не уступят {link:centaurs}кентавр{/link}ам ни единой травинки. Он послал воинов ударить по лагерю Галак прежде, чем его всадники доберутся до деревни, и попросил принести голову их предводителя в предостережение прочим.]=],
		},
		{
			title = "Плененный сын",
			hint = "Узнайте о днях, когда вождя Бейна захватили кентавры.",
			text = [=[Через несколько месяцев после того, как {link:tauren}таурен{/link}ы поселились в {link:mulgore}Мулгор{/link}е, {link:centaurs}кентавр{/link}ы схватили сына верховного вождя. Его отец впал в такое глубокое отчаяние, что не хотел вести народ. Сына нашли и вернули домой {link:orcs}орк{/link} {link:rexxar}Рексар{/link} и таурен Бован Тотем Ветра. Теперь, посылая молодых к отцу, Бейн с гордостью говорит о дне, когда {link:cairne-bloodhoof}Кэрн{/link} выехал вместе с вождем орков {link:thrall}Тралл{/link}ом, чтобы отвоевать эти равнины.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rites-of-the-earthmother}Обряды Матери-Земли{/link}, весть от вождя Лагеря {link:camp-narache}Нараче{/link}]=],
		},
		{ text = "Обряд Видения" },
		{ text = "Раскопки {link:dwarves}дворф{/link}ов" },
		{ text = "Наш древний враг, донесение, которое он получил" },
		{ text = "Верховный вождь" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Кэрн Кровавое Копыто", note = "его отец" },
		{ id = "chief-hawkwind", name = "Вождь Ястребиный Ветер", note = "посылает к нему молодых" },
		{ id = "zarlman-two-moons", name = "Зарлман Две Луны", note = "духовный наставник его деревни" },
		{ id = "brave-wildrunner", name = "Храбрец Вольный Бегун", note = "храбрец его деревни" },
		{ id = "herak-the-pillager", name = "Херак Грабитель", note = "враг" },
	},
})

