			text = [=[Мулн Гнев Земли — шаман-{link:tauren}таурен{/link} и предводитель {link:earthen-ring}Служителей Земли{/link}, совета, который хранит равновесие {link:elements}стихий{/link}. В эти дни долг перед духами увел его за пределы самого мира, в {link:skywall}Небесную Высь{/link}, царство воздуха. Там он ответил на зов ордена {link:windshapers}Ваятелей Ветра{/link}, а вернувшись, привел их с собой.]=],
		},
		{
			title = "Значение",
			text = [=[Мулн — мост между народом {link:skyborne}Рожденных Небом{/link} и миром, имя которому {link:azeroth}Азерот{/link}. Через него орден Ваятелей Ветра нашел Служителей Земли, а через них — {link:horde}Орду{/link}. Эльфы, что спускаются в {link:mulgore}Мулгор{/link}, — его гости, и поначалу они узнают мир через его лагерь и его советы.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он откликнулся на мольбу предводительницы ордена Ваятелей Ветра Айессы Певицы Зари: ее дом гиб.
• Он отправился с шаманами Служителей Земли на {link:zephras-isle}остров Зефрас{/link}, чтобы помочь народу Рожденных Небом.
• Он встал перед одним из великих владык ветра и сказал ему, что у Служителей нет с ним вражды.
• Он предостерег орден Ваятелей Ветра насчет владык стихий и сказал, что есть веская причина бояться {link:al-akir}Ал'Акира{/link}.
• Он открыл путь небесных кораблей между островом Зефрас и {link:mulgore}Мулгор{/link}ом.
• Он держит лагерь на {link:camp-gev-rek}плато Смотрящего в Небо{/link}, куда прибывают новички.]=],
		},
		{
			title = "Неизвестное",
			text = [=[О его жизни до этих дней написано мало. Хроники этой эпохи не сообщают, когда он возглавил Служителей и как {link:ayessa-dawnsinger}Айесса{/link} впервые дотянулась до него через грани миров.]=],
		},
	},
	chapters = {
		{
			title = "Помощь снизу",
			hint = [=[Встаньте рядом с орденом Ваятелей Ветра в их самый темный час на острове Зефрас.]=],
			text = [=[Орден Ваятелей Ветра послал за помощью, и она пришла не скоро. Когда Мулн и шаманы Служителей Земли наконец прибыли, битва с культом верховной жрицы Лортуны уже бушевала. Он попросил прощения за опоздание — его слова были обращены к Айессе. Когда на них обрушился Владыка Восточного Ветра, Мулн говорил от имени Служителей: у них нет с ним вражды, и они просят лишь оставить их в покое. Когда битва закончилась, он тотчас вернулся в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Предостережение",
			hint = [=[Узнайте, что Служители Земли рассказали ордену Ваятелей Ветра о Владыке Ветра.]=],
			text = [=[Мулн многое рассказал о владыках стихий, и {link:ayessa-dawnsinger}Айесса{/link} слушала его. То, что она услышала, вселило в нее страх. Чары, скрывавшие {link:zephras-isle}остров Зефрас{/link}, исчезли, и ничто больше не отделяло остров от владыки {link:al-akir}Ал'Акир{/link}а в его собственных владениях. Верховный старейшина народа Рожденных Небом смотрел дальше: для владыки стихий могут пройти годы или даже десятилетия, прежде чем он обратит взор в их сторону.]=],
		},
		{
			title = "Путь небесных кораблей",
			hint = [=[Отправьтесь на корабле с острова Зефрас в землю Служителей Земли.]=],
			text = [=[Мулн много потрудился, чтобы переправа стала безопасной. Пробные рейсы ходили между островом и {link:mulgore}Мулгор{/link}ом, где обосновались {link:earthen-ring}Служители Земли{/link}, пока небесные корабли не стали ходить постоянно; первые эльфы народа Рожденных Небом уже ждали на другой стороне.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:earthen-ring}Служители Земли{/link}, его лагерь в {link:mulgore}Мулгор{/link}е]=],
		},
		{ text = "Дитя природы" },
		{ text = "Знакомство с Ордой" },
	},
	bonds = {
		{ id = "alaana-stormwalker", name = "Алаана Странница Бурь", note = "встречает орден Ваятелей Ветра в его лагере" },
		{ id = "cairne-bloodhoof", name = "Кэрн Кровавое Копыто", note = "верховный вождь его народа" },
		{ id = "thrall", name = "Тралл", note = "вождь Орды и шаман" },
		{ id = "hamuul-runetotem", name = "Хамуул Рунический Тотем", note = "из Круга Кенария, который привечает его гостей" },
	},
})

Translate("ruRU", "kaga-wildhoof", {
