Translate("ruRU", "bristleback-quilboar", {
	title = "Свинобразы Дыбогривы",
	aliases = { "свинобразы Дыбогривы", "Дыбогривы" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дыбогривы — племя {link:quilboar}свинобразов{/link}, живущее в {link:mulgore}Мулгор{/link}е. Они были здесь до того, как {link:tauren}таурен{/link}ы заселили равнины, и с тех пор воюют с ними. Из своей колючей деревни в Ежевичной лощине они бьют по {link:red-cloud-mesa}Плато Красного Облака{/link}, а их налетчики доходят на севере до самого места п{link:ogres}огр{/link}ебения — Красных скал.]=],
		},
		{
			title = "Как они воюют",
			text = [=[Дыбогривы сражаются из засады. Их воины подстерегают охотничьи отряды {link:tauren}таурен{/link}ов и в темноте прокрадываются в {link:camp-narache}Лагерь Нараче{/link}. Рядом с ними бьются их шаманы. Они растят боевых вепрей, {link:ogres}огр{/link}омных кабанов лощины, злобными и выпускают их на охотничьи угодья тауренов. Их военный вождь составил планы долгой осады Лагеря Нараче.]=],
		},
		{
			title = "В эти дни",
			text = [=[Молодые {link:tauren}таурен{/link}ы {link:camp-narache}Нараче{/link} доказывают свою силу в бою с Дыб{link:ogres}огр{/link}ивами, и пояса павших налетчиков — первые трофеи обряда Силы. В последнее время пришлые Дыбогривы разоряют могилы в Красных скалах. Их вождь, {link:chief-sharptusk-thornmantle}Остроклык Терновая Мантия{/link}, правит лощиной.]=],
		},
	},
})

Translate("ruRU", "palemane-gnolls", {
	title = "Гноллы Бледногривы",
	aliases = { "гноллы Бледногривы", "Бледногривы" },
	sections = {
		{
			title = "Обзор",
			text = [=[Бледногривы — племя {link:gnolls}гноллов{/link}, поселившееся в {link:mulgore}Мулгор{/link}е. Их логово — пещера {link:palemane-rock}Утес Бледногривов{/link} в западных холмах, и они держат лагеря к югу от Деревни Кровавого Копыта. Это браконьеры, живодеры и дубильщики, и они без удержу истребляют зверей равнин.]=],
		},
		{
			title = "Таурены и Бледногривы",
			text = [=[{link:tauren}Таурены{/link} пытались делить с ними землю. Снова и снова они старались заговорить с {link:gnolls}гнолл{/link}ами и каждый раз встречали неуважение. Вождь {link:baine-bloodhoof}Бейн Кровавое Копыто{/link} наконец рассудил, что слова больше не ответ. И все же в эти дни верховный вождь предпринял еще одну попытку и послал к ним своего дальнего ходока {link:perith-stormhoof}Перит{/link}а Грозовое Копыто. Гноллы схватили его и держали в своей пещере.]=],
		},
		{
			title = "Их угодья",
			text = [=[Дубильщики и живодеры племени выделывают шкуры своей добычи вокруг Утеса Бледн{link:ogres}огр{/link}ивов, а браконьеры рыщут по западным холмам. Среди лагерей к югу от Деревни Кровавого Копыта бродит {link:gnolls}гнолл{/link} по кличке Кривое Копье.]=],
		},
	},
})

Translate("ruRU", "windfury-harpies", {
	title = "Гарпии Ярости Ветра",
	aliases = { "гарпии Ярости Ветра", "Ярость Ветра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гарпии Ярости Ветра — это {link:harpies}гарпии{/link} {link:mulgore}Мулгор{/link}а. Их стаи гнездятся на горных кромках юго-востока, вдали от дорог, и прежде всего на Гряде Ярости Ветра на дальнем севере. {link:tauren}Таурены{/link} числят их среди естественных врагов своей земли.]=],
		},
		{
			title = "Природа",
			text = [=[Стаями Ярости Ветра правят матриархи, а их ведьмы и колдуньи повелевают ветром. Они охотятся на все, что ходит под их гнездовьями. Их оперение ценится у {link:tauren}таурен{/link}ов: лазурные и бронзовые перья северных стай идут на головные уборы, которые молодые таурены надевают, представая перед верховным вождем.]=],
		},
		{
			title = "В эти дни",
			text = [=[{link:ruul-eagletalon}Руул Орлиный Коготь{/link} из Деревни Кровавого Копыта посылает молодых воинов против стай юго-востока, чтобы испытать их силу. Северные стаи сильнее, и их колдуньи и матриархи правят высотами Гряды Ярости Ветра. Гарпию по имени сестра {link:scourge}Плеть{/link} Ненависти видели среди северо-западных скал, недалеко от плато, где разбили лагерь {link:earthen-ring}Служители Земли{/link}.]=],
		},
	},
})

Translate("ruRU", "longwalkers", {
	title = "Дальние ходоки",
	aliases = { "дальний ходок" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дальние ходоки — самые доверенные разведчики {link:tauren}таурен{/link}ов. Они подчиняются одному лишь верховному вождю {link:cairne-bloodhoof}Кэрну Кровавому Копыту{/link} и исполняют его самые тайные поручения. Дальнего ходока можно узнать по головной повязке и посоху с перьями. Даже вождь Деревни Кровавого Копыта, родной сын верховного вождя, может лишь просить их о помощи.]=],
		},
		{
			title = "Их обычаи",
			text = [=[Тайна — первый закон дальних ходоков. Они странствуют в одиночку, не говорят о своих поручениях, и когда кого-то из них спасают от опасности, он идет дальше один и никому не рассказывает, куда направляется. Когда дальний ходок не возвращается из дозора, храбрецы ближайшей деревни должны пойти и узнать почему.]=],
		},
		{
			title = "В эти дни",
			text = [=[Двое дальних ходоков попали в беду в {link:mulgore}Мулгор{/link}е. {link:perith-stormhoof}Перит Грозовое Копыто{/link}, которого {link:cairne-bloodhoof}Кэрн{/link} называет своим самым доверенным разведчиком, был послан на переговоры с {link:gnolls}гнолл{/link}ами Бледн{link:ogres}огр{/link}ивами и попал в плен. Мала Долгий Ветер была послана следить за восточной границей, и ее убили {link:centaurs}кентавр{/link}ы Галак; донесение все еще было у нее в руке.]=],
		},
	},
})

Translate("ruRU", "rites-of-the-earthmother", {
	title = "Обряды Матери-Земли",
	aliases = { "Обряды Матери Земли" },
	sections = {
		{
			title = "Обзор",
			text = [=[Обряды Матери-Земли — испытания, которыми молодой {link:tauren}таурен{/link} заслуживает уважение старейшин Громового Утеса. Их три: обряд Силы, обряд Видения и обряд Мудрости. Вместе они ведут от первого лагеря на {link:red-cloud-mesa}Плато Красного Облака{/link} к шатру верховного вождя.]=],
		},
		{
			title = "Три обряда",
			text = [=[• {b}Обряд Силы.{/b} {link:chief-hawkwind}Вождь Ястребиный Ветер{/link} и провидец {link:seer-graytongue}Серый Язык{/link} посылают молодых против налетчиков Дыб{link:ogres}огр{/link}ивов из Ежевичной лощины, чтобы те принесли их пояса в доказательство доблести.
• {b}Обряд Видения.{/b} В Деревне Кровавого Копыта {link:zarlman-two-moons}Зарлман Две Луны{/link} варит Воду провидцев из колодезных камней и янтарных желудей. Выпитая перед костром племени, она вызывает видение равнин, которое ведет испившего к провидцу Мудрому Бегуну.
• {b}Обряд Мудрости.{/b} В Красных скалах духи предков дают благословение тем, кто испил Воды провидцев.]=],
		},
		{
			title = "Конец пути",
			text = [=[Тех, кто прошел обряды, чествуют в Громовом Утесе. Их последний шаг — подняться на самую высокую столовую гору и предстать перед верховным вождем. Но и тогда испытание не окончено. Чтобы они удержали завоеванное место, {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link} посылает их выследить и сразить зверя по кличке Арра'чея, могучего кодо равнин.]=],
		},
	},
})
